import random
import string

from moto.core import ACCOUNT_ID, BaseBackend, BaseModel
from uuid import uuid4

from .exceptions import (
    OriginDoesNotExist,
    InvalidOriginServer,
    DomainNameNotAnS3Bucket,
    DistributionAlreadyExists,
    InvalidIfMatchVersion,
    NoSuchDistribution,
)


def _to_bool(val, default=False):
    if val is None:
        return default
    if isinstance(val, bool):
        return val
    return str(val).lower() == "true"


def _to_list(container, key):
    """
    The XML-request body is parsed into a dictionary, where the `Items`-node
    can either be a single value or a list of values.
    This method normalizes it into a list:

        {"Items": {key: [val1, val2]}}  -->  [val1, val2]
        {"Items": {key: val1}}          -->  [val1]
        {} / None                       -->  []
    """
    if not container:
        return []
    items = container.get("Items") or {}
    values = items.get(key) or []
    if not isinstance(values, list):
        values = [values]
    return values


class ActiveTrustedSigners:
    def __init__(self):
        self.enabled = False
        self.quantity = 0
        self.signers = []


class ActiveTrustedKeyGroups:
    def __init__(self):
        self.enabled = False
        self.quantity = 0
        self.kg_key_pair_ids = []


class LambdaFunctionAssociation:
    def __init__(self, config):
        self.arn = config.get("LambdaFunctionARN") or ""
        self.event_type = config.get("EventType") or ""
        self.include_body = _to_bool(config.get("IncludeBody"))


class FunctionAssociation:
    def __init__(self, config):
        self.arn = config.get("FunctionARN") or ""
        self.event_type = config.get("EventType") or ""


class TrustedSigners:
    def __init__(self, config):
        config = config or {}
        self.enabled = _to_bool(config.get("Enabled"))
        self.signers = _to_list(config, "AwsAccountNumber")


class TrustedKeyGroups:
    def __init__(self, config):
        config = config or {}
        self.enabled = _to_bool(config.get("Enabled"))
        self.key_groups = _to_list(config, "KeyGroup")


class ForwardedValues:
    def __init__(self, config):
        config = config or {}
        self.query_string = _to_bool(config.get("QueryString"))
        cookies = config.get("Cookies") or {}
        self.cookies_forward = cookies.get("Forward") or "none"
        self.whitelisted_names = _to_list(cookies.get("WhitelistedNames"), "Name")
        self.headers = _to_list(config.get("Headers"), "Name")
        self.query_string_cache_keys = _to_list(
            config.get("QueryStringCacheKeys"), "Name"
        )


class CacheBehaviour:
    def __init__(self, config):
        self.path_pattern = config.get("PathPattern") or ""
        self.target_origin_id = config.get("TargetOriginId") or ""
        self.trusted_signers = TrustedSigners(config.get("TrustedSigners"))
        self.trusted_key_groups = TrustedKeyGroups(config.get("TrustedKeyGroups"))
        self.viewer_protocol_policy = config.get("ViewerProtocolPolicy") or ""
        allowed_methods = config.get("AllowedMethods") or {}
        self.allowed_methods = _to_list(allowed_methods, "Method") or ["HEAD", "GET"]
        self.cached_methods = _to_list(allowed_methods.get("CachedMethods"), "Method") or [
            "GET",
            "HEAD",
        ]
        self.smooth_streaming = _to_bool(config.get("SmoothStreaming"))
        self.compress = _to_bool(config.get("Compress"), default=True)
        self.lambda_function_associations = [
            LambdaFunctionAssociation(assoc)
            for assoc in _to_list(
                config.get("LambdaFunctionAssociations"), "LambdaFunctionAssociation"
            )
        ]
        self.function_associations = [
            FunctionAssociation(assoc)
            for assoc in _to_list(
                config.get("FunctionAssociations"), "FunctionAssociation"
            )
        ]
        self.field_level_encryption_id = config.get("FieldLevelEncryptionId") or ""
        self.realtime_log_config_arn = config.get("RealtimeLogConfigArn") or ""
        self.cache_policy_id = config.get("CachePolicyId") or ""
        self.origin_request_policy_id = config.get("OriginRequestPolicyId") or ""
        self.response_headers_policy_id = config.get("ResponseHeadersPolicyId") or ""
        self.forwarded_values = ForwardedValues(config.get("ForwardedValues"))
        self.min_ttl = int(config.get("MinTTL") or 0)
        self.default_ttl = int(config.get("DefaultTTL") or 0)
        self.max_ttl = int(config.get("MaxTTL") or 0)


class Logging:
    def __init__(self, config):
        config = config or {}
        self.enabled = _to_bool(config.get("Enabled"))
        self.include_cookies = _to_bool(config.get("IncludeCookies"))
        self.bucket = config.get("Bucket") or ""
        self.prefix = config.get("Prefix") or ""


class ViewerCertificate:
    def __init__(self, config):
        config = config or {}
        self.cloud_front_default_certificate = _to_bool(
            config.get("CloudFrontDefaultCertificate"), default=True
        )
        self.iam_certificate_id = config.get("IAMCertificateId") or ""
        self.acm_certificate_arn = config.get("ACMCertificateArn") or ""
        self.ssl_support_method = config.get("SSLSupportMethod") or ""
        self.min_protocol_version = config.get("MinimumProtocolVersion") or "TLSv1"
        self.certificate = config.get("Certificate") or ""
        self.certificate_source = config.get("CertificateSource") or "cloudfront"


class Origin:
    def __init__(self, origin):
        self.id = origin.get("Id") or ""
        self.domain_name = origin.get("DomainName") or ""
        self.origin_path = origin.get("OriginPath") or ""
        self.custom_headers = [
            {
                "header_name": header.get("HeaderName") or "",
                "header_value": header.get("HeaderValue") or "",
            }
            for header in _to_list(origin.get("CustomHeaders"), "Header")
        ]
        self.s3_access_identity = ""
        self.custom_origin = None
        self.origin_shield = None
        self.connection_attempts = int(origin.get("ConnectionAttempts") or 3)
        self.connection_timeout = int(origin.get("ConnectionTimeout") or 10)

        if "S3OriginConfig" not in origin and "CustomOriginConfig" not in origin:
            raise InvalidOriginServer

        if "S3OriginConfig" in origin:
            # Very rough validation
            if not self.domain_name.endswith("amazonaws.com"):
                raise DomainNameNotAnS3Bucket
            self.s3_access_identity = (
                origin["S3OriginConfig"].get("OriginAccessIdentity") or ""
            )

        if "CustomOriginConfig" in origin:
            custom_origin = origin["CustomOriginConfig"]
            self.custom_origin = {
                "http_port": int(custom_origin.get("HTTPPort") or 80),
                "https_port": int(custom_origin.get("HTTPSPort") or 443),
                "origin_protocol_policy": custom_origin.get("OriginProtocolPolicy")
                or "",
                "origin_ssl_protocols": _to_list(
                    custom_origin.get("OriginSslProtocols"), "SslProtocol"
                ),
                "origin_read_timeout": int(
                    custom_origin.get("OriginReadTimeout") or 30
                ),
                "origin_keepalive_timeout": int(
                    custom_origin.get("OriginKeepaliveTimeout") or 5
                ),
            }

        if "OriginShield" in origin:
            origin_shield = origin["OriginShield"]
            self.origin_shield = {
                "enabled": _to_bool(origin_shield.get("Enabled")),
                "region": origin_shield.get("OriginShieldRegion") or "",
            }


class OriginGroup:
    def __init__(self, config):
        self.id = config.get("Id") or ""
        failover_criteria = config.get("FailoverCriteria") or {}
        status_codes = failover_criteria.get("StatusCodes") or {}
        self.failover_status_codes = _to_list(status_codes, "StatusCode")
        self.members = _to_list(config.get("Members"), "OriginGroupMember")


class CustomErrorResponse:
    def __init__(self, config):
        self.error_code = int(config.get("ErrorCode") or 0)
        self.response_page_path = config.get("ResponsePagePath") or ""
        self.response_code = config.get("ResponseCode") or ""
        self.error_caching_min_ttl = int(config.get("ErrorCachingMinTTL") or 0)


class DistributionConfig:
    def __init__(self, config):
        self.config = config
        self.caller_reference = config.get("CallerReference") or str(uuid4())
        self.aliases = _to_list(config.get("Aliases"), "CNAME")
        self.default_root_object = config.get("DefaultRootObject") or ""
        self.default_cache_behavior = CacheBehaviour(config["DefaultCacheBehavior"])
        self.cache_behaviors = [
            CacheBehaviour(behavior)
            for behavior in _to_list(config.get("CacheBehaviors"), "CacheBehavior")
        ]
        self.custom_error_responses = [
